        while (temp % i === 0n) {
            factors.set(i, (factors.get(i) || 0n) + 1n);
            temp /= i;
        }
    }
    if (temp > 1n) {
        factors.set(temp, (factors.get(temp) || 0n) + 1n);
    }
    return factors;
}

