        // h[0][a] = p^a for a = 0..e
        // h[t+1][a] = (1/(a+1)) * (h[t][0] + h[t][1] + ... + h[t][a])

        // We only need h[k][e], but we need all h[t][a] for a <= e and t < k

        const maxExp = Number(e);
        // h[t][a] for t in 0..k, a in 0..maxExp
        // Use modular arithmetic

