const MOD = 1000000007n;

function modPow(base, exp, mod) {
    base %= mod;
    if (base < 0) base += mod;
    let result = 1n;
    while (exp > 0n) {
        if (exp % 2n === 1n) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp = exp >> 1n;
    }
    return result;
}

function modInverse(x, mod) {
    return modPow(x, mod - 2n, mod);
}

function factorize(n) {
    const factors = [];
    let temp = n;
    for (let i = 2n; i * i <= temp; i++) {
        if (temp % i === 0n) {
            let count = 0n;
            while (temp % i === 0n) {
                count++;
                temp = temp / i;
            }
            factors.push({ prime: i, exponent: count });
        }
    }
    if (temp > 1n) {
        factors.push({ prime: temp, exponent: 1n });
    }
    return factors;
}

function computeExpectedValueForPrimePower(p, e, k) {
    // p is a prime, e is its exponent, k is the number of steps
    // We need to compute the expected value of p^X where X is the state after k steps
    // Starting from p^e, at each step we pick a divisor uniformly.
    // The divisors of p^a are 1, p, p^2, ..., p^a (a+1 divisors)
    // So from state a, we transition to state j (0 <= j <= a) with probability 1/(a+1)

    // Let dp[i][j] = probability that after i steps, the exponent is j
    // We want sum_{j=0}^{e} dp[k][j] * p^j

    // Since e can be up to ~50 (since 2^50 > 10^15), and k up to 10^4
    // We can use DP with states 0..e

    const maxExp = Number(e);
    const steps = Number(k);

    // dp[j] = probability that current exponent is j
    let dp = new Array(maxExp + 1).fill(0n);
    dp[maxExp] = 1n; // Start with exponent e

    for (let step = 0; step < steps; step++) {
        let newDp = new Array(maxExp + 1).fill(0n);
        for (let a = 0; a <= maxExp; a++) {
            if (dp[a] === 0n) continue;
            // From state a, we can go to any state j where 0 <= j <= a
            // Each with probability 1/(a+1)
            const prob = modInverse(BigInt(a + 1), MOD);
            for (let j = 0; j <= a; j++) {
                newDp[j] = (newDp[j] + dp[a] * prob) % MOD;
            }
        }
        dp = newDp;
    }

    // Compute expected value: sum dp[j] * p^j
    let result = 0n;
    let pPow = 1n;
    const pMod = p % MOD;
    for (let j = 0; j <= maxExp; j++) {
        result = (result + dp[j] * pPow) % MOD;
        pPow = (pPow * pMod) % MOD;
    }

    return result;
}

function main() {
    const line = require('fs').readFileSync('/dev/stdin', 'utf8').trim();
    const parts = line.split(/\s+/);
    const n = BigInt(parts[0]);
    const k = Number(parts[1]);

    const factors = factorize(n);

    let answer = 1n;
    for (const { prime, exponent } of factors) {
        const expected = computeExpectedValueForPrimePower(prime, exponent, k);
        answer = (answer * expected) % MOD;
    }

    console.log(answer.toString());
}

main();
